"""Chargeback response deadline, used by the chargeback skill.

Usage: python deadline.py 2026-09-27 visa
"""
import sys
from datetime import date, timedelta

DAYS = {"visa": 30, "mastercard": 45, "rupay": 30}   # illustrative values

def deadline(dispute_date: str, network: str) -> date:
    return date.fromisoformat(dispute_date) + timedelta(days=DAYS[network.lower()])

if __name__ == "__main__":
    print(deadline(sys.argv[1], sys.argv[2]).isoformat())
